window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c45f06751a06ce7e"]={"versions": [{"id": "FIG-c45f06751a06ce7e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Feature-Baum-Diagramm (Feature Model nach FODA/Kardinalitäts-basiertem Variabilitätsmodell) im Kontext des AUTOSAR Feature Model Exchange Format (FO RS FeatureModelExchangeFormat, Use Case UC_FMDT_00006). Es veranschaulicht hierarchische Feature-Dekompositionen sowie querschneidende Abhängigkeiten (Cross-Tree Constraints) über direkte Relationen (<code>Requires</code>, <code>Conflicts</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Wurzelelement <code>Feature Model: Sample Car</code> dekomponiert in drei obligatorische Teilmerkmale (<code>Mandatory</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Country</code> mit den ausschließenden Kind-Alternativen (<code>Alternative</code>): <code>Germany</code>, <code>UK</code>, <code>US</code>.</li>\n<li><code>Steering Wheel</code> mit den ausschließenden Kind-Alternativen (<code>Alternative</code>): <code>Left</code>, <code>Right</code>.</li>\n<li><code>Speedometer display</code> mit den ausschließenden Kind-Alternativen (<code>Alternative</code>): <code>km/h</code>, <code>mph</code>.</li>\n</ul>\n<p class=\"fig-p\">Querschneidende Relationen zwischen den alternativen Features:</p>\n<ul class=\"fig-list\">\n<li><code>Requires</code> (gestrichelte Pfeillinien mit offener Pfeilspitze):</li>\n<li><code>Germany</code> erfordert <code>Left</code></li>\n<li><code>US</code> erfordert <code>Left</code></li>\n<li><code>UK</code> erfordert <code>Right</code></li>\n<li><code>Conflicts</code> (gestrichelte Pfeillinien mit offener Pfeilspitze):</li>\n<li><code>Germany</code> schließt <code>mph</code> aus (<code>Conflicts</code> mit <code>mph</code>)</li>\n<li><code>US</code> schließt <code>km/h</code> aus (<code>Conflicts</code> mit <code>km/h</code>)</li>\n<li><code>UK</code> schließt <code>km/h</code> aus (<code>Conflicts</code> mit <code>km/h</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Variabilitätsmodell ohne Laufzeitsequenz. Bei der Modellauflösung/Konfigurationsauswahl gilt:</p>\n<ol class=\"fig-list\">\n<li>Genau ein Land aus <code>Country</code> muss ausgewählt werden (<code>Germany</code>, <code>UK</code> oder <code>US</code>).</li>\n<li>Die Auswahl eines Landes triggert deterministisch die <code>Requires</code>-Beziehung zur Festlegung der Lenkradposition (<code>Left</code> bzw. <code>Right</code>).</li>\n<li>Parallel sperren die <code>Conflicts</code>-Beziehungen inkompatible Tachometereinheiten (z. B. <code>Germany</code> verbietet <code>mph</code>; <code>US</code> und <code>UK</code> verbieten <code>km/h</code>), sodass unter Berücksichtigung der Alternativ-Bedingung für <code>Speedometer display</code> die jeweils zulässige Einheit selektiert werden muss.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt die Spezifikation von Abhängigkeiten mittels einfacher gerichteter Schlüsselwort-Relationen (<code>Requires</code>, <code>Conflicts</code>) als Alternative zu booleschen Restriktionsformeln (Restrictions). Die Relationen gehen von den Ursprungsmerkmalen (<code>Country</code>-Features) aus. Dies erlaubt das Entkoppeln von Merkmalen, wenn Zielmerkmale (<code>Steering Wheel</code>, <code>Speedometer display</code>) organisations- oder lieferantenseitig nicht modifiziert werden dürfen (Read-Only / Third-Party Ownership). Werkzeuge für den Feature-Model-Austausch müssen diese Relationstypen semantisch abbilden und bei der Validierung auflösen können.</p>"}, {"id": "FIG-4658341aad612f10", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / Feature-Baum-Diagramm (Feature Model nach FODA/Kardinalitäts-basiertem Variabilitätsmodell) im Kontext des AUTOSAR Feature Model Exchange Format (FO RS FeatureModelExchangeFormat, Use Case UC_FMDT_00006). Es veranschaulicht hierarchische Feature-Dekompositionen sowie querschneidende Abhängigkeiten (Cross-Tree Constraints) über direkte Relationen (<code>Requires</code>, <code>Conflicts</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Wurzelelement <code>Feature Model: Sample Car</code> dekomponiert in drei obligatorische Teilmerkmale (<code>Mandatory</code>):</p>\n<ul class=\"fig-list\">\n<li><code>Country</code> mit den ausschließenden Kind-Alternativen (<code>Alternative</code>): <code>Germany</code>, <code>UK</code>, <code>US</code>.</li>\n<li><code>Steering Wheel</code> mit den ausschließenden Kind-Alternativen (<code>Alternative</code>): <code>Left</code>, <code>Right</code>.</li>\n<li><code>Speedometer display</code> mit den ausschließenden Kind-Alternativen (<code>Alternative</code>): <code>km/h</code>, <code>mph</code>.</li>\n</ul>\n<p class=\"fig-p\">Querschneidende Relationen zwischen den alternativen Features:</p>\n<ul class=\"fig-list\">\n<li><code>Requires</code> (gestrichelte Pfeillinien mit offener Pfeilspitze):</li>\n<li><code>Germany</code> erfordert <code>Left</code></li>\n<li><code>US</code> erfordert <code>Left</code></li>\n<li><code>UK</code> erfordert <code>Right</code></li>\n<li><code>Conflicts</code> (gestrichelte Pfeillinien mit offener Pfeilspitze):</li>\n<li><code>Germany</code> schließt <code>mph</code> aus (<code>Conflicts</code> mit <code>mph</code>)</li>\n<li><code>US</code> schließt <code>km/h</code> aus (<code>Conflicts</code> mit <code>km/h</code>)</li>\n<li><code>UK</code> schließt <code>km/h</code> aus (<code>Conflicts</code> mit <code>km/h</code>)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations- und Variabilitätsmodell ohne Laufzeitsequenz. Bei der Modellauflösung/Konfigurationsauswahl gilt:</p>\n<ol class=\"fig-list\">\n<li>Genau ein Land aus <code>Country</code> muss ausgewählt werden (<code>Germany</code>, <code>UK</code> oder <code>US</code>).</li>\n<li>Die Auswahl eines Landes triggert deterministisch die <code>Requires</code>-Beziehung zur Festlegung der Lenkradposition (<code>Left</code> bzw. <code>Right</code>).</li>\n<li>Parallel sperren die <code>Conflicts</code>-Beziehungen inkompatible Tachometereinheiten (z. B. <code>Germany</code> verbietet <code>mph</code>; <code>US</code> und <code>UK</code> verbieten <code>km/h</code>), sodass unter Berücksichtigung der Alternativ-Bedingung für <code>Speedometer display</code> die jeweils zulässige Einheit selektiert werden muss.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Zeigt die Spezifikation von Abhängigkeiten mittels einfacher gerichteter Schlüsselwort-Relationen (<code>Requires</code>, <code>Conflicts</code>) als Alternative zu booleschen Restriktionsformeln (Restrictions). Die Relationen gehen von den Ursprungsmerkmalen (<code>Country</code>-Features) aus. Dies erlaubt das Entkoppeln von Merkmalen, wenn Zielmerkmale (<code>Steering Wheel</code>, <code>Speedometer display</code>) organisations- oder lieferantenseitig nicht modifiziert werden dürfen (Read-Only / Third-Party Ownership). Werkzeuge für den Feature-Model-Austausch müssen diese Relationstypen semantisch abbilden und bei der Validierung auflösen können.</p>"}], "trans": [{"from": "FIG-c45f06751a06ce7e", "to": "FIG-4658341aad612f10", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
